INSERT INTO `news` (`id`, `title`, `slug`, `description`, `featured_image`, `content`, `news_category_id`, `status`, `scheduled_at`, `published_at`, `is_active`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Integral lanza nueva funcionalidad de reportes en línea', 'integral-lanza-nueva-funcionalidad-de-reportes-en-linea', 'La plataforma incorpora un módulo de reportes personalizables para que los usuarios administren su información de forma más ágil.', 'https://demo.web-informatica.info/adminintegral/public/storage/media/images/8031b76a-249f-4c65-acf4-07e7c7dae774.webp', '<h2 style=\"text-align: center;\">Nueva funcionalidad de reportes en l&iacute;nea</h2>\n<p>El equipo de desarrollo de Integral se complace en anunciar el lanzamiento de una nueva funcionalidad de reportes en l&iacute;nea, disponible ya para todos los usuarios de la plataforma.</p>\n<h3>Principales beneficios</h3>\n<p>Esta actualizaci&oacute;n permite generar <span style=\"text-decoration: underline;\">reportes personalizados</span> de <em>manera m&aacute;s r&aacute;pida</em> y sencilla.</p>\n<ul>\n<li>Generaci&oacute;n de reportes en tiempo real.</li>\n<li>Filtros avanzados por fecha y categor&iacute;a.</li>\n<li>Exportaci&oacute;n en m&uacute;ltiples formatos.</li>\n</ul>\n<ol>\n<li>Ingresar al m&oacute;dulo de Reportes.</li>\n<li>Seleccionar el rango de fechas.</li>\n<li>Elegir el formato de exportaci&oacute;n.</li>\n<li>Descargar el archivo generado.</li>\n</ol>\n<p><span style=\"background-color: #34495e; color: #e67e23;\">Disponible a partir de esta semana para todos los planes.</span></p>', 1, 'published', NULL, '2026-07-22 20:58:14', 1, 1, 1, '2026-07-22 20:58:14', '2026-07-22 21:23:30', NULL);
INSERT INTO `news_categories` (`id`, `name`, `slug`, `is_active`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Actualizaciones', 'actualizaciones', 1, 1, 1, '2026-07-22 20:53:35', '2026-07-22 20:53:35', NULL);
INSERT INTO `pages` (`id`, `title`, `slug`, `html_content`, `css_content`, `js_content`, `components_json`, `styles_json`, `is_published`, `created_by`, `updated_by`, `created_at`, `updated_at`, `footer_id`, `navbar_id`) VALUES
(1, 'Inicio', 'inicio', '<section data-gjs-type=\"banner-single-component\" data-banner-id=\"1\" id=\"i4tu\"><div class=\"bsingle-wrapper\"><div class=\"bsingle-content-wrapper\">\n                        </div><div class=\"bsingle-stripe\">\n                        </div></div></section><section class=\"ab-section\"><div class=\"ab-grid\"><div class=\"ab-content-col flex flex-col gap-4\"><h2 class=\"text-4xl font-bold text-[#003B71]\">Nuestra Historia</h2><p class=\"text-base text-[#003B71] leading-relaxed text-justify\">Banco Integral nació en <span class=\"ab-highlight font-bold\">1990</span> como un proyecto de créditos de la Fundación Salvadoreña de Apoyo Integral FUSAI, apoyado por naciones Unidas, evoluciono a través de los años hasta convertirse en Banco Integral, S.A.</p><p class=\"text-base text-[#003B71] leading-relaxed text-justify\">Nuestra Institución está enfocada en acompañar el desarrollo de los empresarios de la micro y pequeña empresa de El Salvador con productos y servicios financieros especializados e innovadores adaptados a sus necesidades, teniendo al cliente como eje central de todas operaciones.</p><p class=\"text-base text-[#003B71] leading-relaxed text-justify\">Contamos con <span class=\"ab-highlight font-bold\">27</span> agencias y más de <span class=\"ab-highlight font-bold\">1000</span> puntos de pago distribuidos en El Salvador, acompañando a miles de salvadoreños para impulsar el crecimiento de sus negocios por medio de productos y servicios financieros, que incluyen valores agregados como:</p><ul class=\"ab-bullet-list\"><li>Educación financiera</li><li>Programas de formación empresarial</li><li>Asistencia técnica constructiva gratuita para créditos de mejora de viviendas</li><li>Asimismo ofrecemos otros servicios como: Microseguros de salud, vida y pago de remesas.</li></ul></div><div class=\"ab-image-col\"><div class=\"ab-image-wrap\"><img src=\"/storage/media/images/2674f6b1-e9f1-42a6-8dab-3a00bd525974.png\" alt=\"Asesor financiero\" id=\"ivr1nv\"/></div></div></div></section><section class=\"mvv-section\"><h2 class=\"mvv-section-title\">Misión, Visión y Valores</h2><div class=\"mvv-grid\"><div class=\"mvv-card\"><h3 class=\"mvv-card-title\">Misión</h3><p class=\"mvv-card-text\">Proveemos la mejor experiencia a los empresarios de la micro y pequeña empresa, sus familiares y sus empleados, acompañándolos en su desarrollo con productos y servicios financieros especializados e innovadores adaptados a sus necesidades</p></div><div class=\"mvv-card\"><h3 class=\"mvv-card-title\">Visión</h3><p class=\"mvv-card-text\">Ser el banco pionero de la revolución financiera digital para los empresarios de la micro y pequeña empresa; y que mejor comprende y sirve sus necesidades de desarrollo a través de un ecosistema de productos y servicios integrales e innovadores.\".</p></div><div class=\"mvv-card\"><h3 class=\"mvv-card-title\">Valores</h3><p class=\"mvv-card-text\">Cada día la cultura Integral se está fortaleciendo, todos los que pertenecemos a esta organización compartimos y vivimos los valores</p><ul class=\"mvv-bullet-list\"><li>Responsabilidad</li><li>Compromiso social</li><li>Integridad</li><li>Excelencia</li></ul></div></div></section><div data-gjs-type=\"product-cards-component\" data-product-cards-config=\"{&quot;heading&quot;:&quot;Créditos&quot;,&quot;subheading&quot;:&quot;Opciones de financiamiento diseñadas para hacer realidad tus proyectos.&quot;,&quot;more_href&quot;:&quot;#&quot;,&quot;more_label&quot;:&quot;Ver más&quot;,&quot;show_more&quot;:true,&quot;cards&quot;:[{&quot;img&quot;:&quot;/storage/media/images/9a9796d4-a535-4787-a8ac-b9708c3085f7.webp&quot;,&quot;title&quot;:&quot;CREDINVIERTE&quot;,&quot;desc&quot;:&quot;Adquiere activos fijos&quot;,&quot;href&quot;:&quot;#&quot;,&quot;btn_label&quot;:&quot;Solicitar&quot;},{&quot;img&quot;:&quot;/storage/media/images/5e38b25b-72ee-41b5-9604-bcc9a46775e2.webp&quot;,&quot;title&quot;:&quot;SOLUCIONES INTEGRALES&quot;,&quot;desc&quot;: