INSERT INTO `scripts` (`id`, `name`, `description`, `type`, `scope`, `page_slugs`, `js_content`, `css_content`, `status`, `is_active`, `rejection_reason`, `reviewed_by`, `reviewed_at`, `approved_by`, `approved_at`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'Botón Flotante WhatsApp', 'Botón flotante en esquina inferior derecha que abre WhatsApp al hacer clic', 'js', 'global', NULL, '(function() {\r\n    var btn = document.createElement(\'a\');\r\n    btn.href = \'https://wa.me/50212345678\';\r\n    btn.target = \'_blank\';\r\n    btn.rel = \'noopener noreferrer\';\r\n    btn.className = \'floating-whatsapp-btn\';\r\n    btn.setAttribute(\'aria-label\', \'Escríbenos por WhatsApp\');\r\n\r\n    var ring = document.createElement(\'span\');\r\n    ring.className = \'floating-whatsapp-ring\';\r\n    btn.appendChild(ring);\r\n\r\n    var icon = document.createElement(\'i\');\r\n    icon.className = \'ri-whatsapp-line floating-whatsapp-icon\';\r\n    btn.appendChild(icon);\r\n\r\n    document.body.appendChild(btn);\r\n})();', '.floating-whatsapp-btn {\r\n    position: fixed;\r\n    bottom: 24px;\r\n    right: 24px;\r\n    z-index: 9999;\r\n    width: 60px;\r\n    height: 60px;\r\n    background: #ffffff;\r\n    border-radius: 50%;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    text-decoration: none;\r\n    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.18);\r\n    transition: box-shadow 0.25s ease;\r\n}\r\n\r\n.floating-whatsapp-btn:hover {\r\n    box-shadow: 0 6px 22px rgba(0, 0, 0, 0.26);\r\n}\r\n\r\n.floating-whatsapp-icon {\r\n    font-size: 30px;\r\n    color: #E97300;\r\n    line-height: 1;\r\n    position: relative;\r\n    z-index: 2;\r\n}\r\n\r\n.floating-whatsapp-ring {\r\n    position: absolute;\r\n    inset: 0;\r\n    border-radius: 50%;\r\n    border: 2px solid #E97300;\r\n    opacity: 0;\r\n    animation: floating-whatsapp-pulse 2.4s ease-out infinite;\r\n}\r\n\r\n@keyframes floating-whatsapp-pulse {\r\n    0% {\r\n        opacity: 0.55;\r\n        box-shadow: 0 0 0 0 rgba(233, 115, 0, 0.35);\r\n    }\r\n    70% {\r\n        opacity: 0;\r\n        box-shadow: 0 0 0 14px rgba(233, 115, 0, 0);\r\n    }\r\n    100% {\r\n        opacity: 0;\r\n        box-shadow: 0 0 0 0 rgba(233, 115, 0, 0);\r\n    }\r\n}\r\n\r\n@media (max-width: 640px) {\r\n    .floating-whatsapp-btn {\r\n        width: 52px;\r\n        height: 52px;\r\n        bottom: 18px;\r\n        right: 18px;\r\n    }\r\n    .floating-whatsapp-icon {\r\n        font-size: 26px;\r\n    }\r\n}', 'approved', 1, NULL, NULL, NULL, 1, '2026-07-01 23:34:45', 1, 1, '2026-06-12 15:11:10', '2026-07-01 23:34:49'),
(2, 'TweenCode Widget', 'Widget de TweenCode', 'js', 'global', NULL, '(function() {\r\n  var script = document.createElement(\'script\');\r\n  script.src = \'https://widgets.tweencode.co/beta/widget.iife.js\';\r\n  script.setAttribute(\'data-token\', \'aak_svvyScx1JtT3lMGISXlvqjCHHrFqUp1RZtRVVQbALXE\');\r\n  script.async = true;\r\n  document.head.appendChild(script);\r\n})();', NULL, 'approved', 1, NULL, NULL, NULL, 1, '2026-08-17 14:12:46', 1, 1, '2026-08-17 13:55:39', '2026-08-17 14:32:02');
